  IsFloat(event: any) {
    let key = window.event ? event.which : event.keyCode;
    let chark = String.fromCharCode(key);
    let tempValue = event.currentTarget.value + chark;
    if (key >= 48 && key <= 57) {
      if (this.filter(tempValue) === false) {
        return false;
      } else {
        return true;
      }
    } else {
      if (key == 8 || key == 13 || key == 0) {
        return true;
      } else if (key == 46) {
        if (this.filter(tempValue) === false) {
          return false;
        } else {
          return true;
        }
      } else {
        return false;
      }
    }
  }

  filter(__val__: any) {
    let preg = /^([0-9]+\.?[0-9]{0,2})$/;
    if (preg.test(__val__) === true) {
      return true;
    } else {
      return false;
    }
  }

